function decode(value: string): Uint8Array {
  const binary = atob(value);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
  return bytes;
}

let regular: Uint8Array | null = null;
let bold: Uint8Array | null = null;

export function regularLatinFont(): Uint8Array {
  regular ??= decode(REGULAR.replace(/\s/g, ''));
  return regular;
}

export function boldLatinFont(): Uint8Array {
  bold ??= decode(BOLD.replace(/\s/g, ''));
  return bold;
}
